                is_line = True
                break
        if not is_line:
            for j in range(len(grid[0])):
                if sum(grid[i][j] for i in range(len(grid))) == cnt and cnt>1:
                    is_line = True
                    break
        if is_line:
            line_colors.append(c)
        else:
            centre_color = c

    # Determine the length of the lines (they all have the same length)
    L = None
    for c in line_colors:
        for i,row in enumerate(grid):
            if row.count(c)>0:
                # horizontal line
                if row.count(c) > 1:
                    L = row.count(c)
                    break
        if L is not None:
            break
        for j in range(len(grid[0])):
            col_cnt = sum(grid[i][j] for i in range(len(grid)))
            if col_cnt>1:
                L = col_cnt
                break
        if L is not None:
            break

    # size of output
    N = L + 2

    # initialise output grid with zeros
    out = [[0]*N for _ in range(N)]

    # identify the four lines: top, bottom, left, right
    # gather positions of each line
    horiz = []   # (row, color)
    vert  = []   # (col, color)
    for c in line_colors:
        # find one occurrence
        for i,row in enumerate(grid):
            if c in row:
                j = row.index(c)
                if all(grid[i][jj]==c for jj in range(j, j+L)):
                    # horizontal line
                    horiz.append((i,c))
                    break
        else:
            # vertical line
            for j in range(len(grid[0])):
                if sum(grid[i][j] for i in range(len(grid))) == L:
                    vert.append((j,c))
                    break

    # sort to get topmost/bottommost and leftmost/rightmost
    horiz.sort(key=lambda x: x[0])
    vert.sort(key=lambda x: x[0])
    top_color   = horiz[0][1]
    bottom_color= horiz[-1][1]
    left_color  = vert[0][1]
    right_color = vert[-1][1]

    # draw the border lines
    for c in range(1, L+1):
        out[0][c] = top_color          # top
        out[N-1][c] = bottom_color    # bottom
        out[c][0] = left_color        # left
        out[c][N-1] = right_color     # right

    # draw the central X pattern (diagonal + anti‑diagonal) inside the interior
    for i in range(L):
        for j in range(L):
            if i == j or i + j == L - 1:
                # do not write the centre cell when L is even (it will be overwritten anyway)
                if not (L % 2 == 0 and i == j == L//2):
                    out[i+1][j+1] = centre_color

    # place one connector for each side, at the interior position closest to the middle of the line
    mid = L // 2           # 0‑based index inside the interior
    # top connector
    out[1][mid+1] = top_color
    # bottom connector
    out[N-2][mid+1] = bottom_color
    # left connector
    out[mid+1][1] = left_color
    # right connector
    out[mid+1][N-2] = right_color

    return out
